initJs:
function(container, apiUrl, tables) {
  let allResults = [];
  let stores = [];
  let products = [];
  let forecasts = [];

  // テーブル再描画関数
  function renderResults(results) {
    const tbody = container.querySelector("#results-tbody");
    if (!results || results.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted);">計算結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = results.map(result => `
      <tr data-id="${result.id || ''}">
        <td><a href="#" class="product-link" data-product-id="${result.productId || ''}" style="color: var(--primary); text-decoration: none;">${result.productName || ''}</a></td>
        <td>${result.productCode || ''}</td>
        <td style="text-align: right;">${result.forecastDemand || 0}</td>
        <td style="text-align: right;">${result.currentStock || 0}</td>
        <td style="text-align: right;">${result.safetyStock || 0}</td>
        <td style="text-align: right; font-weight: bold; color: var(--primary);">${result.recommendedOrder || 0}</td>
        <td>${result.orderTiming || '-'}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${result.id || ''}">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.style.display = "block";
    setTimeout(() => {
      errorDiv.style.display = "none";
    }, 5000);
  }

  // バリデーション
  function validateInputs() {
    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const periodStart = container.querySelector("#period-start").value;
    const periodEnd = container.querySelector("#period-end").value;
    const safetyStock = container.querySelector("#safety-stock").value;
    const leadTime = container.querySelector("#lead-time").value;
    const orderPoint = container.querySelector("#order-point").value;

    if (!storeId) {
      showError("店舗を選択してください");
      return false;
    }
    if (!category) {
      showError("商品カテゴリを選択してください");
      return false;
    }
    if (!periodStart || !periodEnd) {
      showError("計算対象期間を設定してください");
      return false;
    }
    if (new Date(periodStart) > new Date(periodEnd)) {
      showError("期間の開始日は終了日より前に設定してください");
      return false;
    }
    if (safetyStock && (parseInt(safetyStock) < 0 || parseInt(safetyStock) > 9999)) {
      showError("安全在庫数は0以上9999以下の値を入力してください");
      return false;
    }
    if (leadTime && (parseInt(leadTime) < 1 || parseInt(leadTime) > 365)) {
      showError("リードタイムは1以上365以下の値を入力してください");
      return false;
    }
    if (orderPoint && parseInt(orderPoint) < 0) {
      showError("発注点は0以上の値を入力してください");
      return false;
    }

    return true;
  }

  // 発注量計算実行
  async function executeCalculation() {
    if (!validateInputs()) return;

    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const periodStart = container.querySelector("#period-start").value;
    const periodEnd = container.querySelector("#period-end").value;
    const safetyStock = parseInt(container.querySelector("#safety-stock").value) || 50;
    const leadTime = parseInt(container.querySelector("#lead-time").value) || 7;
    const orderPoint = parseInt(container.querySelector("#order-point").value) || 100;

    try {
      // 需要予測データ取得をシミュレート
      const forecastData = await window.aivicApi.list(8); // 需要予測結果テーブル
      if (!forecastData) {
        showError("需要予測データの取得に失敗しました");
        return;
      }

      // 商品データ取得をシミュレート
      const productData = await window.aivicApi.list(2); // 商品マスタテーブル
      if (!productData) {
        showError("在庫データの取得に失敗しました");
        return;
      }

      // カテゴリに応じた商品をフィルタリング
      const categoryProducts = productData.filter(p => 
        p.商品カテゴリID && p.商品カテゴリID.includes(category)
      );

      // 計算結果を生成
      const calculationResults = categoryProducts.map(product => {
        const forecast = forecastData.find(f => f.商品ID === product.商品ID && f.店舗ID === storeId);
        const forecastDemand = forecast ? forecast.予測数量 || 0 : Math.floor(Math.random() * 200) + 50;
        const currentStock = Math.floor(Math.random() * 500) + 100;

        // 発注量計算ロジック
        const demandDuringLeadTime = Math.ceil(forecastDemand * leadTime / 30);
        const recommendedOrder = Math.max(0, (demandDuringLeadTime + safetyStock) - currentStock);

        const orderTiming = currentStock <= orderPoint ? "即時発注" : 
                           currentStock <= (orderPoint + safetyStock) ? "要注意" : "正常";

        return {
          id: `calc_${product.商品ID}`,
          productId: product.商品ID,
          productName: product.商品名,
          productCode: product.商品コード,
          forecastDemand,
          currentStock,
          safetyStock,
          recommendedOrder,
          orderTiming
        };
      });

      allResults = calculationResults;
      renderResults(allResults);

      // サマリー表示更新
      const totalCurrentStock = allResults.reduce((sum, r) => sum + r.currentStock, 0);
      const totalRecommendedOrder = allResults.reduce((sum, r) => sum + r.recommendedOrder, 0);
      const urgentOrders = allResults.filter(r => r.orderTiming === "即時発注").length;

      container.querySelector("#current-stock").textContent = totalCurrentStock.toLocaleString();
      container.querySelector("#recommended-order").textContent = totalRecommendedOrder.toLocaleString();
      container.querySelector("#order-timing").textContent = urgentOrders > 0 ? `${urgentOrders}件 要発注` : "正常";

      // 需要予測結果表示更新
      const forecastDisplay = container.querySelector("#forecast-display");
      forecastDisplay.innerHTML = `
        <div style="color: var(--text);">
          <div style="margin-bottom: 10px;"><strong>対象期間:</strong> ${periodStart} ～ ${periodEnd}</div>
          <div style="margin-bottom: 10px;"><strong>対象商品数:</strong> ${allResults.length}件</div>
          <div style="margin-bottom: 10px;"><strong>総予測需要量:</strong> ${allResults.reduce((sum, r) => sum + r.forecastDemand, 0).toLocaleString()}個</div>
          <div><strong>計算完了時刻:</strong> ${new Date().toLocaleString()}</div>
        </div>
      `;

    } catch (error) {
      showError("計算処理中にエラーが発生しました: " + error.message);
    }
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 店舗データ読み込み
      const storeData = await window.aivicApi.list(1);
      if (storeData) {
        stores = storeData;
        const storeSelect = container.querySelector("#store-select");
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          stores.map(store => `<option value="${store.店舗ID}">${store.店舗名}</option>`).join('');
      }

      // 初期表示
      renderResults([]);
    } catch (error) {
      console.error("初期データ読み込みエラー:", error);
    }
  }

  // 検索機能
  function performSearch() {
    const keyword = container.querySelector("#search-input").value.toLowerCase();
    if (!keyword) {
      renderResults(allResults);
      return;
    }

    const filtered = allResults.filter(result => 
      (result.productName || '').toLowerCase().includes(keyword) ||
      (result.productCode || '').toLowerCase().includes(keyword)
    );
    renderResults(filtered);
  }

  // CSVエクスポート
  function exportCSV() {
    if (!allResults || allResults.length === 0) {
      showError("エクスポートするデータがありません");
      return;
    }

    const headers = ['商品名', '商品コード', '予測需要量', '現在在庫', '安全在庫', '推奨発注量', '発注タイミング'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...allResults.map(result => [
        `"${result.productName || ''}"`,
        `"${result.productCode || ''}"`,
        result.forecastDemand || 0,
        result.currentStock || 0,
        result.safetyStock || 0,
        result.recommendedOrder || 0,
        `"${result.orderTiming || ''}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注量計算結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // イベントリスナー設定
  container.querySelector("#btn-calculate").addEventListener("click", executeCalculation);

  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#store-select").value = "";
    container.querySelector("#category-select").value = "";
    container.querySelector("#period-start").value = "";
    container.querySelector("#period-end").value = "";
    container.querySelector("#safety-stock").value = "";
    container.querySelector("#lead-time").value = "";
    container.querySelector("#order-point").value = "";

    allResults = [];
    renderResults([]);

    container.querySelector("#current-stock").textContent = "-";
    container.querySelector("#recommended-order").textContent = "-";
    container.querySelector("#order-timing").textContent = "-";

    const forecastDisplay = container.querySelector("#forecast-display");
    forecastDisplay.innerHTML = '<div style="color: var(--text-muted);">計算条件を設定して「計算実行」ボタンをクリックしてください</div>';
  });

  container.querySelector("#btn-search").addEventListener("click", performSearch);
  container.querySelector("#search-input").addEventListener("keypress", (e) => {
    if (e.key === "Enter") performSearch();
  });

  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // 行レベル操作のイベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const resultId = detailBtn.dataset.id;
      const result = allResults.find(r => r.id === resultId);
      if (result) {
        alert(`商品詳細\n\n商品名: ${result.productName}\n商品コード: ${result.productCode}\n予測需要: ${result.forecastDemand}\n現在在庫: ${result.currentStock}\n推奨発注量: ${result.recommendedOrder}`);
      }
      return;
    }

    const productLink = e.target.closest(".product-link");
    if (productLink) {
      e.preventDefault();
      const productId = productLink.dataset.productId;
      // 商品詳細画面への遷移（実装されている場合）
      console.log("商品詳細画面へ遷移:", productId);
      return;
    }
  });

  // 初期データ読み込み実行
  loadInitialData();
}
